-- https://docs.snowflake.com/en/sql-reference/sql/alter-storage-lifecycle-policy

-- RENAME TO
ALTER STORAGE LIFECYCLE POLICY my_slp
  RENAME TO my_renamed_slp;

-- IF EXISTS with RENAME
ALTER STORAGE LIFECYCLE POLICY IF EXISTS my_slp
  RENAME TO my_new_slp;

-- SET BODY (update the policy expression)
ALTER STORAGE LIFECYCLE POLICY my_slp
  SET BODY ->
    event_ts < DATEADD(DAY, -30, CURRENT_TIMESTAMP());

-- SET ARCHIVE_TIER
ALTER STORAGE LIFECYCLE POLICY my_slp
  SET ARCHIVE_TIER = COOL;

-- SET ARCHIVE_FOR_DAYS
ALTER STORAGE LIFECYCLE POLICY my_slp
  SET ARCHIVE_FOR_DAYS = 180;

-- SET COMMENT
ALTER STORAGE LIFECYCLE POLICY my_db.my_schema.my_slp
  SET COMMENT = 'Updated retention policy';

-- UNSET ARCHIVE_FOR_DAYS
ALTER STORAGE LIFECYCLE POLICY my_slp
  UNSET ARCHIVE_FOR_DAYS;

-- UNSET COMMENT
ALTER STORAGE LIFECYCLE POLICY my_slp
  UNSET COMMENT;
